{{--
    Contact CTA — the teal card that closes the homepage.

    The markup, the class names and the nesting below are the designer's own,
    taken from the reference template so that the compiled stylesheet in
    `public/template/css/template.css` matches it rule for rule. Only the
    content is ours: the heading and body are the approved wording rather than
    the placeholder lines the template shipped with, and every button goes to
    the real contact route instead of the reference's `?enquiry=` links, which
    nothing on our contact page reads.

    The template animates with Framer Motion, which leaves inline
    `opacity`/`transform` styles behind — those are stripped and replaced with
    the site's own `reveal-on-scroll` hook, so nothing is left invisible if a
    bundle fails to load. The inline sizes on the decorative rings are not from
    Framer and stay: they are what gives each ring its diameter. Each button
    keeps the Framer pair of arrow icons; they share one grid cell and one
    icon, so with the animation styles gone they simply sit on top of each
    other and read as the single arrow the design intends.

    The reference also carried a third, tourism button. The approved copy for
    this section covers Hajj and Umrah only, so that button is not emitted here.
--}}

<section id="contact-cta" class="bg-sand-100 pb-16 pt-4 sm:pb-20 lg:pb-24">
    <div class="mx-auto w-full max-w-[var(--container-site)] px-5 sm:px-8 lg:px-10">
        <div class="reveal-on-scroll">
            <div class="relative isolate overflow-hidden rounded-[26px] bg-gradient-teal px-7 py-11 shadow-[0_24px_60px_-28px_rgba(6,18,25,0.65)] sm:rounded-[34px] sm:px-12 sm:py-14 lg:px-16">
                <div aria-hidden="true" class="pointer-events-none absolute right-0 top-1/2 -z-10 hidden sm:block"><span style="width:640px;height:640px" class="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 rounded-full bg-ivory/[0.055]"></span><span style="width:500px;height:500px" class="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 rounded-full bg-ivory/[0.055]"></span><span style="width:380px;height:380px" class="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 rounded-full bg-ivory/[0.055]"></span><span style="width:270px;height:270px" class="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 rounded-full bg-ivory/[0.055]"></span><span style="width:170px;height:170px" class="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 rounded-full bg-ivory/[0.055]"></span></div>
                <div class="max-w-xl">
                    <h2 class="font-display text-3xl font-semibold leading-[1.12] tracking-tight text-heading sm:text-4xl lg:text-[42px]">Your Sacred Journey Begins with a Conversation</h2>
                    <p class="mt-4 max-w-lg text-sm leading-relaxed text-ivory/70 sm:mt-5 sm:text-base">Whether you are preparing for Hajj, planning Umrah or simply need guidance before making a decision, our experienced team is ready to assist you.</p>
                    <p class="mt-7 text-[11px] font-semibold uppercase tracking-[0.24em] text-accent-400 sm:mt-8 sm:text-xs">Speak to Universal Brothers Today</p>
                    <div class="mt-5 flex flex-col gap-3.5 sm:mt-6 sm:flex-row sm:flex-wrap sm:items-center sm:gap-4"><a class="group relative isolate inline-flex items-center gap-3 overflow-hidden rounded-pill font-semibold tracking-wide will-change-transform bg-[length:200%_100%] bg-right bg-no-repeat hover:bg-left focus-visible:bg-left transition-[background-position,color,border-color] duration-500 ease-[cubic-bezier(0.22,1,0.36,1)] motion-reduce:duration-0 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent-500 focus-visible:ring-offset-2 focus-visible:ring-offset-transparent disabled:pointer-events-none disabled:opacity-50 text-inverse shadow-lg shadow-accent-900/25 hover:text-ivory h-10 pl-5 pr-1.5 text-xs sm:h-12 sm:pl-6 sm:pr-2 sm:text-sm w-full justify-between sm:w-auto sm:justify-start" style="background-image:linear-gradient(to right, var(--color-brand-700) 0 50%, var(--color-accent-500) 50% 100%)" href="{{ route('contact') }}"><span class="relative">Hajj Enquiry</span><span class="relative grid shrink-0 place-items-center overflow-hidden rounded-full transition-colors duration-300 bg-ivory text-accent-700 group-hover:text-inverse size-7 sm:size-8"><span class="col-start-1 row-start-1 flex"><svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-arrow-up-right"><path d="M7 7h10v10"></path><path d="M7 17 17 7"></path></svg></span><span class="col-start-1 row-start-1 flex"><svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-arrow-up-right"><path d="M7 7h10v10"></path><path d="M7 17 17 7"></path></svg></span></span></a><a class="group relative isolate inline-flex items-center gap-3 overflow-hidden rounded-pill font-semibold tracking-wide will-change-transform bg-[length:200%_100%] bg-right bg-no-repeat hover:bg-left focus-visible:bg-left transition-[background-position,color,border-color] duration-500 ease-[cubic-bezier(0.22,1,0.36,1)] motion-reduce:duration-0 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent-500 focus-visible:ring-offset-2 focus-visible:ring-offset-transparent disabled:pointer-events-none disabled:opacity-50 text-inverse shadow-lg shadow-brand-950/20 hover:text-inverse h-10 pl-5 pr-1.5 text-xs sm:h-12 sm:pl-6 sm:pr-2 sm:text-sm w-full justify-between sm:w-auto sm:justify-start" style="background-image:linear-gradient(to right, var(--color-accent-500) 0 50%, var(--color-ivory) 50% 100%)" href="{{ route('contact') }}"><span class="relative">Umrah Enquiry</span><span class="relative grid shrink-0 place-items-center overflow-hidden rounded-full transition-colors duration-300 bg-accent-500 text-inverse group-hover:bg-ivory group-hover:text-accent-700 size-7 sm:size-8"><span class="col-start-1 row-start-1 flex"><svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-arrow-up-right"><path d="M7 7h10v10"></path><path d="M7 17 17 7"></path></svg></span><span class="col-start-1 row-start-1 flex"><svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-arrow-up-right"><path d="M7 7h10v10"></path><path d="M7 17 17 7"></path></svg></span></span></a><a class="group mt-1 inline-flex items-center gap-2 self-start rounded-sm text-sm font-medium text-ivory/75 transition-colors duration-300 hover:text-accent-400 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent-500 focus-visible:ring-offset-4 focus-visible:ring-offset-brand-900 sm:ml-2 sm:mt-0 sm:self-auto" href="{{ route('contact') }}"><span class="relative">Contact Our Team<span aria-hidden="true" class="absolute -bottom-0.5 left-0 h-px w-full origin-left scale-x-0 bg-accent-400 transition-transform duration-300 group-hover:scale-x-100"></span></span><svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-arrow-right transition-transform duration-300 group-hover:translate-x-1"><path d="M5 12h14"></path><path d="m12 5 7 7-7 7"></path></svg></a></div>
                </div>
            </div>
        </div>
    </div>
</section>
